:root{--ink:#1e2e27;--ink-soft:#5c7069;--cream:#f4f8f0;--paper:#fff;--line:#e2eadf;--line-strong:#cbdac7;--mint:#1b8168;--mint-soft:#d8f0e6;--lime-soft:#eaf2ce;--lime-fg:#56701f;--danger:#b23b3b;--danger-soft:#f6e4e2;--stage:#edf1ea;--teal-soft:#d9ecec;--orange:#ff6a0d}
*{box-sizing:border-box}
body{font-family:Figtree,'Segoe UI',system-ui,sans-serif;color:var(--ink);background:var(--stage)}
.wrap{max-width:560px;margin:0 auto;padding:20px 16px}
h1{font-family:'Bricolage Grotesque','Segoe UI',sans-serif;font-size:24px;margin:0}
h2{font-family:'Bricolage Grotesque','Segoe UI',sans-serif;font-size:18px;margin:0 0 4px}
.soft{color:var(--ink-soft);font-size:12.5px}
.card{background:var(--paper);border:1px solid var(--line);border-radius:22px;padding:20px;margin-top:16px}
.row{background:var(--cream);border:1px solid var(--line);border-radius:16px;padding:12px 14px;margin-top:10px;display:flex;align-items:center;gap:12px}
.btn{min-height:44px;width:100%;border:0;border-radius:13px;background:var(--mint);color:#fff;font-weight:800;font-size:13.5px;padding:11px 16px;margin-top:10px}
.btn[aria-disabled=true]{background:var(--line-strong);color:var(--ink-soft)}
.btn-ghost{min-height:44px;width:100%;border:1px solid var(--line-strong);background:var(--paper);color:var(--ink);border-radius:13px;padding:10px 16px;font-weight:700;font-size:13.5px;margin-top:10px}
.btn-pts{background:var(--orange)}
.pill{display:inline-block;border-radius:999px;padding:2px 10px;font-size:10.5px;font-weight:800}
.pill-mint{background:var(--mint-soft);color:var(--mint)}
.pill-lime{background:var(--lime-soft);color:var(--lime-fg)}
.pill-pts{background:#ffe6d5;color:#a3410a}
label.l{font-size:13px;font-weight:700;display:block;margin-top:14px}
input.t,select.t{width:100%;min-height:44px;border:1px solid var(--line-strong);border-radius:12px;padding:10px 12px;font-size:14px;margin-top:6px;background:var(--paper)}
.info{background:var(--lime-soft);color:var(--lime-fg);border-radius:14px;padding:10px 13px;font-size:12.5px;font-weight:600;margin-top:12px}
.warn{background:var(--danger-soft);color:var(--danger);border-radius:14px;padding:10px 13px;font-size:12.5px;font-weight:700;margin-top:12px}
.err{color:var(--danger);font-size:12.5px;font-weight:700;margin-top:6px}
.stepper{display:flex;align-items:center;gap:8px;margin-top:6px}
.stepper button{width:48px;height:48px;border-radius:12px;border:1px solid var(--line-strong);background:var(--paper);font-size:22px;font-weight:800;color:var(--ink)}
.stepper input{flex:1;height:48px;text-align:center;font-size:20px;font-weight:800;border:1px solid var(--line-strong);border-radius:12px}
.stepper input[aria-invalid=true]{border-color:var(--danger);background:var(--danger-soft)}
.stepper .unit{font-weight:800;color:var(--ink-soft)}
.sugg{display:flex;justify-content:space-between;margin-top:8px;font-size:12.5px}
.sugg b{color:var(--mint)}
.modes{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-top:14px}
.modes button{min-height:52px;border-radius:13px;border:1px solid var(--line-strong);background:var(--paper);font-weight:800;font-size:13px}
.modes button[aria-pressed=true]{background:var(--mint);border-color:var(--mint);color:#fff}
.modes button.pts[aria-pressed=true]{background:var(--orange);border-color:var(--orange)}
.photo{display:flex;gap:8px;margin-top:8px}.photo div{width:64px;height:64px;border-radius:12px;background:var(--cream);border:1px dashed var(--line-strong);display:flex;align-items:center;justify-content:center;font-size:22px;color:var(--ink-soft)}
.photo div.on{background:linear-gradient(135deg,#cfe3d6,#a7c9b5);border:0}
.stat{flex:1;background:var(--cream);border:1px solid var(--line);border-radius:16px;padding:14px;text-align:center}.stat b{font-family:'Bricolage Grotesque',sans-serif;font-size:28px;display:block}
.kv{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--line);font-size:14px}.kv:last-child{border:0}.kv b{font-weight:800}
.sheet{background:var(--paper);border-radius:22px 22px 0 0;padding:20px;box-shadow:0 -6px 30px rgb(20 28 24/.18);margin-top:16px}
.scrim{background:rgb(20 28 24/.55);padding:40px 0 0;border-radius:22px}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px}
.tile{background:var(--paper);border:1px solid var(--line);border-radius:18px;overflow:hidden;position:relative}
.tile .img{height:120px;background:linear-gradient(135deg,#d9ecec,#b9d8d0)}
.tile .badge{position:absolute;top:8px;left:8px;border-radius:999px;padding:3px 10px;font-size:11px;font-weight:800;background:#fff}
.tile .badge.gift{color:var(--mint)}.tile .badge.swap{color:#2b6e8f}.tile .badge.pts{background:var(--orange);color:#fff}
.tile .body{padding:10px 12px;font-size:13px;font-weight:700}
.chips{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px}
.chips button{border:1px solid var(--line-strong);background:var(--paper);border-radius:999px;padding:8px 14px;font-weight:700;font-size:13px}
.chips button[aria-pressed=true]{background:var(--ink);border-color:var(--ink);color:#fff}
.hist{display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid var(--line);font-size:13.5px}
.plus{color:var(--mint);font-weight:800}.minus{color:var(--danger);font-weight:800}.neutral{color:var(--ink-soft);font-weight:800}

